#include <vector>

class Solution {
public:
    int numOfSubarrays(std::vector<int>& arr) {
        const int MOD = 1e9 + 7;
        long long even = 1, odd = 0, cur = 0, ans = 0;
        for (int x : arr) {
            cur += x;
            if (cur % 2 != 0) {
                ans = (ans + even) % MOD;
                odd++;
            } else {
                ans = (ans + odd) % MOD;
                even++;
            }
        }
        return ans;
    }
};

class Solution {
    public int numOfSubarrays(int[] arr) {
        final int MOD = 1000000007;
        long even = 1, odd = 0, cur = 0, ans = 0;
        for (int x : arr) {
            cur += x;
            if (cur % 2 != 0) {
                ans = (ans + even) % MOD;
                odd++;
            } else {
                ans = (ans + odd) % MOD;
                even++;
            }
        }
        return (int) ans;
    }
}

var numOfSubarrays = function(arr) {
    const MOD = 1000000007n;
    let even = 1n, odd = 0n, cur = 0n, ans = 0n;
    for (const x of arr) {
        cur += BigInt(x);
        if (cur % 2n !== 0n) {
            ans = (ans + even) % MOD;
            odd++;
        } else {
            ans = (ans + odd) % MOD;
            even++;
        }
    }
    return Number(ans);
};
